    {
      "keystrokes": "cd /app\n",
      "duration": 0.1
    },
    {
      "keystrokes": "grep -n \"runProgram\\|this.pc\\|nextPc\\|delaySlot\\|case 0x00:\\|function_field\\|0x0c\\|0x0C\\|syscall\\|case 0x28:\\|case 0x29:\\|case 0x2b:\\|jr(\\|jalr(\\|mult(\\|div(\\|mflo(\\|mfhi(\" /app/vm.js | head -200\n",
      "duration": 0.1
    },
    {
      "keystrokes": "awk 'NR>=1000 && NR<=1120 {print NR \":\" $0}' /app/vm.js\n",
      "duration": 0.1
    },
    {
      "keystrokes": "awk 'NR>=1300 && NR<=1450 {print NR \":\" $0}' /app/vm.js\n",
      "duration": 0.1
    },
    {
      "keystrokes": "awk 'NR>=1520 && NR<=1710 {print NR \":\" $0}' /app/vm.js\n",
